(() => {
'use strict';
const D=window.A2_CARDS, root=document.getElementById('content');
const KEY='greek-a2-card-prototype-v1';
const cardById=new Map(D.cards.map(c=>[c.id,c]));
let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{}
let moduleId=D.modules.some(m=>m.id===saved.moduleId)?saved.moduleId:'gender';
const entry=new URLSearchParams(location.search);
if(D.modules.some(m=>m.id===entry.get('topic')))moduleId=entry.get('topic');
let view=['introduction','training','practice','grammar'].includes(entry.get('view'))?entry.get('view'):'introduction',introIndex=0,session=null,selected='',checked=false,selfReview=false;
const drafts=saved.drafts&&typeof saved.drafts==='object'?saved.drafts:{};
const marks=saved.marks&&typeof saved.marks==='object'?saved.marks:{};
let pending=saved.session;
function validSession(s){return s&&Array.isArray(s.queue)&&s.queue.length>0&&s.queue.length<=60&&s.queue.every(x=>x&&cardById.has(x.id)&&Number.isInteger(x.retry)&&x.retry>=0&&x.retry<=2)&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.queue.length&&['training','practice'].includes(s.mode)&&Array.isArray(s.results)&&s.results.length<=60&&Array.isArray(s.original)&&s.original.every(id=>cardById.has(id));}
if(!validSession(pending))pending=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify({moduleId,drafts,marks,session:session||pending}))}catch{}}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function button(text,action,cls=''){return `<button class="${cls}" data-action="${action}">${text}</button>`}
function source(c){return `<details class="meta"><summary>Тема и связь с материалами</summary><p>Авторское задание. ${c.sourceRefs.map(r=>`${esc(D.sources[r.source].title)} · PDF ${r.pdfPages.join(', ')}${r.printed?' · '+esc(r.printed):''}`).join('<br>')}</p></details>`}
function nav(v){if(session){pending=session;session=null;persist()}if('speechSynthesis'in window)speechSynthesis.cancel();view=v;selected='';checked=false;selfReview=false;render()}
function setModule(id){if(!D.modules.some(m=>m.id===id))return;moduleId=id;introIndex=0;persist();render()}
function moduleOptions(){return D.modules.map(m=>`<option value="${m.id}" ${m.id===moduleId?'selected':''}>${esc(m.title)}</option>`).join('')}
function intro(){const m=D.modules.find(x=>x.id===moduleId);const items=D.cards.filter(c=>c.moduleId===moduleId&&c.stage==='introduction');
 if(!items.length)return `<article class="card"><span class="tag">Ситуации A2</span><h2>Переносим знания в жизнь</h2><p>Прочитай объявление, найди деталь, послушай сообщение, напиши письмо или разыграй диалог.</p><p>В тренировке есть поддержка. В самостоятельной отработке ты выбираешь формат. Для письма и речи используются опора и самопроверка.</p>${button('Выбрать задание','practice','primary')}${button('Все темы грамматики','grammar','link-button')}</article>`;
 const c=items[Math.min(introIndex,items.length-1)];return `<div class="layout"><aside class="panel"><span class="tag">Введение</span><h3>Сначала разберёмся</h3><p class="intro-note">Одна мысль, короткий пример и частая ошибка.</p><label class="info-line" for="topic">Тема</label><select id="topic" class="topic-select">${moduleOptions()}</select><div class="steps"><b>${introIndex+1} / ${items.length}</b> объяснения</div>${button('К грамматике','grammar','secondary wide')}</aside><article class="card"><span class="tag">${esc(m.subtitle)}</span><h2>${esc(c.prompt)}</h2><p>${esc(c.body)}</p><div class="example" lang="el">${esc(c.example)}</div><div class="actions">${introIndex===0?button('Дальше: частая ошибка','intro-next','primary'):button('Потренировать эту тему','topic-training','primary')}${introIndex?button('Назад','intro-back','secondary'):''}${button('Сразу к отработке','topic-practice','secondary')}</div>${source(c)}</article></div>`}
function grammar(){return `<div class="progress-top"><div><span class="tag">Грамматика</span><h2>От «какой род?» к целой фразе</h2></div></div><p class="muted">Выбери тему. В каждой — объяснение, примеры, три упражнения и применение в ситуации.</p><div class="module-grid">${D.modules.filter(m=>m.category==='grammar').map((m,i)=>`<button class="module" data-module="${m.id}"><span class="num">${String(i+1).padStart(2,'0')} · ${D.cards.filter(c=>c.moduleId===m.id&&marks[c.id]).length} из ${D.cards.filter(c=>c.moduleId===m.id).length} карточек пройдено</span><strong>${esc(m.title)}</strong><span>${esc(m.subtitle)}</span></button>`).join('')}</div><details class="about"><summary>Следующие темы курса</summary><p>${D.roadmap.map(esc).join(' · ')}</p></details>`}
function training(){return `<div class="layout"><aside class="panel"><span class="tag">Приложение ведёт</span><h3>Твоя короткая сессия</h3><ol class="side-list"><li>Ответь на вопрос.</li><li>Прочитай объяснение.</li><li>Вернись к сложному позже.</li></ol></aside><article class="card"><span class="tag">Тренировка · A1 → A2</span><h2>Десять маленьких шагов</h2><p>От простого выбора формы — к пониманию объявления. Задания уже собраны, остаётся начать.</p><div class="pillrow"><span>10 заданий</span><span>Около 4–6 минут</span><span>Повторение ошибок</span></div>${pending?.mode==='training'?`<div class="resume"><p>Сохранена тренировка: шаг ${pending.index+1}.</p>${button('Продолжить','resume','primary')}</div>`:''}<div class="actions">${button('Начать новую тренировку','start-training','primary')}${button('Разобрать грамматику','grammar','secondary')}</div><p class="info-line">В этом прототипе используется готовая последовательность. Подбор по истории обучения — следующий этап.</p></article></div>`}
function practice(){return `<article class="card"><span class="tag">Ты управляешь</span><h2>Практика в своём темпе</h2><p>Существующая практика с глаголами сохраняется в приложении. Здесь можно отдельно попробовать новые карточки грамматики и ситуаций.</p><div class="module-grid"><label for="topic">Тема<select id="topic" class="topic-select">${moduleOptions()}</select></label><label for="card-type">Формат<select id="card-type" class="type-select"><option value="all">Все упражнения темы</option><option value="choice">Выбор ответа / чтение</option><option value="input">Ввод формы</option><option value="listening">Слушание</option><option value="writing">Письмо</option><option value="speaking">Речь</option></select></label></div>${pending?.mode==='practice'?`<div class="resume">Есть незавершённая отработка. ${button('Продолжить','resume')}</div>`:''}<div class="actions">${button('Начать выбранное','start-practice','primary')}${button('Прочитать объяснение','introduction','secondary')}</div><p id="setup-status" role="status" class="inline-status"></p></article>`}
function start(ids,mode){if(!ids.length){document.getElementById('setup-status').textContent='В этой теме нет такого формата. Выбери другой формат или «Ситуации A2».';return}pending=null;session={mode,queue:ids.map(id=>({id,retry:0})),original:[...ids],index:0,results:[],startedAt:Date.now()};selected='';checked=false;selfReview=false;persist();render()}
function current(){return cardById.get(session.queue[session.index].id)}
function exercise(){const c=current(),entry=session.queue[session.index],isOpen=c.assessment==='self';
 const done=session.results.filter(x=>x.retry===0).length;const heading=session.mode==='training'?'Тренировка':'Самостоятельная отработка';
 let field='';
 if(c.type.startsWith('listening'))field=`<div class="notice">Пробное аудио: голос устройства на греческом. ${button('Слушать','listen')}<p id="audio-status" role="status"></p></div><details class="meta"><summary>Показать текст (подсказка)</summary><p lang="el">${esc(c.transcript)}</p></details>`;
 if(c.options)field+=`<div class="options">${c.options.map((o,i)=>`<button class="option" data-option="${i}" aria-pressed="${selected===o}" ${checked?'disabled':''}>${esc(o)}</button>`).join('')}</div>`;
 else if(isOpen)field+=`<label for="response">${c.type==='writing'?'Твой текст':'Заметки к ответу (произнеси ответ вслух)'}</label><textarea id="response" ${checked?'readonly':''} placeholder="${c.type==='writing'?'Γεια σου…':'Можно записать опорные фразы…'}">${esc(drafts[c.id]||'')}</textarea><p class="count" id="word-count"></p>`;
 else field+=`<label for="response">Твой ответ</label><input id="response" autocomplete="off" lang="${c.type==='listening-input'?'ru':'el'}" value="${esc(selected)}" ${checked?'disabled':''}>`;
 let review='';if(selfReview){review=`<div class="feedback"><strong>Самопроверка</strong><p>${esc(c.feedback)}</p><div class="checklist">${c.rubric.map((r,i)=>`<label><input type="checkbox" data-check="${i}"><span>${esc(r)}</span></label>`).join('')}</div><details><summary>Посмотреть пример ответа</summary><p lang="el">${esc(c.modelAnswer).replace(/\n/g,'<br>')}</p></details>${button('Завершить самопроверку','self-complete','primary')}${button('Вернуться к ответу','self-back','link-button')}</div>`}
 const result=session.results.find(x=>x.index===session.index);
 if(checked&&result&&!isOpen)review=`<div class="feedback ${result.correct?'':'incorrect'}" role="status"><strong>${result.correct?'Верно!':'Разберём ответ'}</strong>${!result.correct?`<p>Правильный ответ: <b>${esc(c.answer)}</b></p>`:''}<p>${esc(c.feedback)}</p>${entry.retry<2&&session.mode==='training'&&!result.correct?'<p>Эта карточка вернётся через несколько заданий.</p>':''}</div>`;
 return `<article class="card"><div class="progress-top"><span class="tag">${heading}</span>${button('Сохранить и выйти','exit','secondary')}</div><div class="progress-top"><span>${entry.retry?'Повторение сложного':'Задание '+(done+(checked?0:1))+' из '+session.original.length}</span><span class="info-line">${esc(c.skill==='grammar'?'Грамматика':({reading:'Чтение',listening:'Слушание',writing:'Письмо',speaking:'Речь'}[c.skill]))}</span></div><div class="progress" role="progressbar" aria-label="Основные задания" aria-valuemin="0" aria-valuemax="${session.original.length}" aria-valuenow="${done}"><span style="width:${done/session.original.length*100}%"></span></div><h2>${esc(c.prompt)}</h2>${c.context?`<div class="context" lang="el">${esc(c.context)}</div>`:''}${field}${!checked&&!selfReview?`<div class="actions"><button class="primary" id="check" data-action="${isOpen?'self-review':'check'}" ${!isOpen&&!selected.trim()?'disabled':''}>${isOpen?'Перейти к самопроверке':'Проверить'}</button>${c.hint?'<details><summary>Подсказка</summary><p>'+esc(c.hint)+'</p></details>':''}</div>`:''}${review}${checked?`<div class="actions">${button('Продолжить','next','primary')}</div>`:''}${source(c)}</article>`}
function normalize(s){return s.normalize('NFC').trim().toLocaleLowerCase('el').replace(/\s+/g,' ')}
function check(){if(checked||!session||!selected.trim())return;const c=current(),entry=session.queue[session.index];const ok=c.acceptedAnswers.some(x=>normalize(x)===normalize(selected));session.results.push({id:c.id,index:session.index,retry:entry.retry,correct:ok});marks[c.id]=true;checked=true;if(!ok&&session.mode==='training'&&entry.retry<2){const pos=Math.min(session.index+D.reviewPolicy.delay+1,session.queue.length);session.queue.splice(pos,0,{id:c.id,retry:entry.retry+1})}persist();render()}
function finish(){const s=session;const first=s.results.filter(x=>x.retry===0&&typeof x.correct==='boolean');const correct=first.filter(x=>x.correct).length;const unresolved=[...new Set(s.results.filter(x=>x.correct===false).map(x=>x.id))].filter(id=>s.results.filter(x=>x.id===id).at(-1).correct===false);const reviewed=s.results.filter(x=>x.self).length;
 session=null;pending=null;persist();root.innerHTML=`<article class="card"><span class="tag">Сессия завершена</span><h2>Ещё один шаг к уверенному греческому</h2>${first.length?`<div class="big">${correct} / ${first.length}</div><p>Верно с первой попытки. Повторения не увеличивают эту точность.</p>`:''}${reviewed?`<p>${reviewed} заданий с самопроверкой. Это не автоматическая оценка речи или письма.</p>`:''}<p>Повторений: ${s.results.filter(x=>x.retry>0).length}. Ещё стоит закрепить: ${unresolved.length}.</p>${unresolved.length?`<ul>${unresolved.map(id=>`<li>${esc(cardById.get(id).prompt)}</li>`).join('')}</ul>`:''}<div class="actions">${button('Ещё тренировка','start-training','primary')}${button('Выбрать тему','grammar','secondary')}</div></article>`}
function render(){document.querySelectorAll('nav button').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});root.innerHTML=session?exercise():({introduction:intro,training,practice,grammar}[view])();updateWords()}
function updateWords(){const el=document.getElementById('word-count');if(!el||!session)return;const c=current(),count=(drafts[c.id]||'').trim().split(/\s+/u).filter(Boolean).length;el.textContent=c.wordTarget?`${count} слов · ориентир ${c.wordTarget[0]}–${c.wordTarget[1]}. Содержание и язык проверь отдельно.`:'Ответ произнеси вслух; запись в этом прототипе не ведётся.'}
function speak(){const status=document.getElementById('audio-status');if(!('speechSynthesis'in window)){status.textContent='Озвучка недоступна. Можно открыть текст под заданием.';return}const voices=speechSynthesis.getVoices();const voice=voices.find(v=>v.lang.toLowerCase().startsWith('el'));if(!voice){status.textContent='Греческий голос не найден на устройстве. Открой текст под заданием; это будет чтение с подсказкой.';return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(current().audioText);u.lang='el-GR';u.voice=voice;u.rate=.85;u.onerror=()=>{status.textContent='Не удалось воспроизвести. Открой текст под заданием.'};status.textContent='Пробное чтение на греческом.';speechSynthesis.speak(u)}
document.querySelector('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)nav(b.dataset.view)});
root.addEventListener('change',e=>{if(e.target.id==='topic')setModule(e.target.value)});
root.addEventListener('input',e=>{if(e.target.id!=='response')return;if(current().assessment==='self'){drafts[current().id]=e.target.value;persist();updateWords()}else{selected=e.target.value;session.response=selected;persist();document.getElementById('check').disabled=!selected.trim()}});
root.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='response'&&e.target.tagName==='INPUT'){e.preventDefault();check()}});
root.addEventListener('click',e=>{const mod=e.target.closest('[data-module]');if(mod){setModule(mod.dataset.module);nav('introduction');return}const opt=e.target.closest('[data-option]');if(opt&&!checked){selected=current().options[Number(opt.dataset.option)];session.response=selected;persist();render();return}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(['introduction','training','practice','grammar'].includes(action)){nav(action);return}
 switch(action){case'intro-next':{const c=D.cards.filter(c=>c.moduleId===moduleId&&c.stage==='introduction')[introIndex];if(c)marks[c.id]=true;introIndex++;persist();render();break;}case'intro-back':introIndex=Math.max(0,introIndex-1);render();break;case'start-training':view='training';start(D.trainingPlan,'training');break;case'topic-training':{const c=D.cards.filter(c=>c.moduleId===moduleId&&c.stage==='introduction')[introIndex];if(c)marks[c.id]=true;persist()}view='training';start(D.cards.filter(c=>c.moduleId===moduleId&&c.stage!=='introduction').map(c=>c.id),'training');break;case'topic-practice':nav('practice');break;case'start-practice':{const type=document.getElementById('card-type').value;const ids=D.cards.filter(c=>c.moduleId===moduleId&&c.stage!=='introduction'&&(type==='all'||c.type===type||(type==='listening'&&c.type.startsWith('listening')))).map(c=>c.id);start(ids,'practice');break}case'resume':session=pending;pending=null;view=session.mode;selected=typeof session.response==='string'?session.response:'';checked=session.results.some(x=>x.index===session.index);selfReview=false;render();break;case'exit':nav(session.mode);break;case'check':check();break;case'next':if('speechSynthesis'in window)speechSynthesis.cancel();if(session.index+1>=session.queue.length){finish();return}session.index++;session.response='';selected='';checked=false;selfReview=false;persist();render();break;case'listen':speak();break;case'self-review':selfReview=true;render();break;case'self-back':selfReview=false;render();break;case'self-complete':if(checked)return;session.results.push({id:current().id,index:session.index,retry:session.queue[session.index].retry,self:true,checkedItems:[...root.querySelectorAll('[data-check]:checked')].map(x=>Number(x.dataset.check))});marks[current().id]=true;checked=true;selfReview=false;persist();render();break;
 }});
render();
})();
